#!/bin/bash

# Use this script to benchmark all cluster sizes for one key-value store
# The variable names in REQUIRED_VARS are those exported by the hosts.env.
# Adapt to your desired SUT. The file is generated by ./02_configure_instances.yml
#
# Also make sure to adapt the output file names.
# (ctrl + f or :s/redis/valkey/gc might be useful here)

set -e

# Make sure latest state is loaded
source hosts.env

# Array of required environment variables
REQUIRED_VARS=(
    "HOST_REDIS1_IP"
    "HOST_REDIS2_IP"
    "HOST_REDIS3_IP"
    "HOST_REDIS4_IP"
    "HOST_REDIS5_IP"
)

echo "Checking environment variables..."

# Make sure variables are actually set
for var in "${REQUIRED_VARS[@]}"; do
    if [[ -z "${!var}" ]]; then
        echo "Error: Environment variable '$var' is missing or empty."
        exit 1
    fi
done

echo "All environment variables present. Starting benchmarks..."
echo "-------------------------------------------------------"

run_benchmark() {
    local output_name=$1
    local ips=$2

    echo "Running benchmark"
    echo "Target IPs: $ips"
    echo "Output: $output_name.csv"
    
    ansible-playbook 03_run_benchmark.yml \
        -i inventory_gcp_compute.yml \
        --vault-password-file pw \
        --extra-vars "target_ip=$ips output_file=$output_name"
    
    echo "Finished $output_name."
    echo "-------------------------------------------------------"
}

#----------- Five nodes -----------#

# Join nodes to a cluster
if [[ "$REQUIRED_VARS[0]" != *"ACDIS"* ]]; then
  redis-cli --cluster create ${!REQUIRED_VARS[0]}:7000 ${!REQUIRED_VARS[1]}:7000 ${!REQUIRED_VARS[2]}:7000 ${!REQUIRED_VARS[3]}:7000 ${!REQUIRED_VARS[4]}:7000 --cluster-replicas 0 --cluster-yes
fi

run_benchmark "redis_five_nodes" "${!REQUIRED_VARS[0]},${!REQUIRED_VARS[1]},${!REQUIRED_VARS[2]},${!REQUIRED_VARS[3]},${!REQUIRED_VARS[4]}"

#------------------
# Prepare Scanario Four nodes

if [[ "$REQUIRED_VARS[0]" != *"ACDIS"* ]]; then
  # Bring instances to clean state
  for node in ${REQUIRED_VARS[@]}; do
    IP=${!node}
    ssh -o StrictHostKeyChecking=No nils@$IP << 'EOF'
      sudo systemctl stop redis-cluster
      sudo rm /home/nils/cluster/nodes.conf
      sudo systemctl start redis-cluster
EOF
  done
else
  # Stop the last node
  ssh -o StrictHostKeyChecking=No nils@${!REQUIRED_VARS[-1]} "sudo systemctl stop acdis"
  # Restart all others
  for node in "${REQUIRED_VARS[@]:0:4}"; do
    IP=${!node}
    ssh -o StrictHostKeyChecking=No nils@$IP "sudo systemctl restart acdis"
    sleep 5
  done
fi

# Shutdown unused node to save money
# ssh -o StrictHostKeyChecking=No nils@$HOST_REDIS5_IP "sudo poweroff"

if [[ "$REQUIRED_VARS[0]" != *"ACDIS"* ]]; then
  redis-cli --cluster create ${!REQUIRED_VARS[0]}:7000 ${!REQUIRED_VARS[1]}:7000 ${!REQUIRED_VARS[2]}:7000 ${!REQUIRED_VARS[3]}:7000 --cluster-replicas 0 --cluster-yes
fi

# Scenario: Four Nodes
run_benchmark "redis_four_nodes" "${!REQUIRED_VARS[0]},${!REQUIRED_VARS[1]},${!REQUIRED_VARS[2]},${!REQUIRED_VARS[3]}"

#------------------
# Prepare Scenario Three Nodes

if [[ "$REQUIRED_VARS[0]" != *"ACDIS"* ]]; then
  for node in "${REQUIRED_VARS[@]:0:4}"; do
    IP=${!node}
    ssh -o StrictHostKeyChecking=No nils@$IP << 'EOF'
      sudo systemctl stop redis-cluster
      sudo rm /home/nils/cluster/nodes.conf
      sudo systemctl start redis-cluster
EOF
  done
else
  ssh -o StrictHostKeyChecking=No nils@${!REQUIRED_VARS[-2]} "sudo systemctl stop acdis"
  for node in "${REQUIRED_VARS[@]:0:3}"; do
    IP=${!node}
    ssh -o StrictHostKeyChecking=No nils@$IP "sudo systemctl restart acdis"
    sleep 5
  done
fi

# Shutdown unused node to save money
# ssh -o StrictHostKeyChecking=No nils@$HOST_REDIS4_IP "sudo poweroff"

# Let cluster boot up
sleep 3

if [[ "$REQUIRED_VARS[0]" != *"ACDIS"* ]]; then
  redis-cli --cluster create ${!REQUIRED_VARS[0]}:7000 ${!REQUIRED_VARS[1]}:7000 ${!REQUIRED_VARS[2]}:7000 --cluster-replicas 0 --cluster-yes
fi

# Scenario: Three Nodes
run_benchmark "redis_three_nodes" "${!REQUIRED_VARS[0]},${!REQUIRED_VARS[1]},${!REQUIRED_VARS[2]}"
#---------------------
# Prepare single node benchmark

if [[ "$REQUIRED_VARS[0]" != *"ACDIS"* ]]; then
  for node in "${REQUIRED_VARS[@]:0:3}"; do
    IP=${!node}
    ssh -o StrictHostKeyChecking=No nils@$IP << 'EOF'
      sudo systemctl stop redis-cluster
      sudo rm /home/nils/cluster/nodes.conf
      sudo systemctl start redis-cluster
EOF
  done
else
  ssh -o StrictHostKeyChecking=No nils@${!REQUIRED_VARS[1]} "sudo systemctl stop acdis"
  ssh -o StrictHostKeyChecking=No nils@${!REQUIRED_VARS[2]} "sudo systemctl stop acdis"
  sleep 3
  ssh -o StrictHostKeyChecking=No nils@${!REQUIRED_VARS[0]} "sudo systemctl restart acdis"
fi

# Shutdown unused nodes to save money
# ssh -o StrictHostKeyChecking=No nils@$HOST_REDIS3_IP "sudo poweroff"
# ssh -o StrictHostKeyChecking=No nils@$HOST_REDIS2_IP "sudo poweroff"

# Let cluster boot up
sleep 3

# Scenario: One Node
run_benchmark "redis_one_node" "${!REQUIRED_VARS[0]}"

echo "All benchmarks completed successfully."
